  rd_l2_foot_guide: { en: "User guide", fil: "Gabay sa user", zh: "使用指南", "zh-TW": "使用指南", vi: "Hướng dẫn sử dụng", th: "คู่มือการใช้งาน", id: "Panduan pengguna", bg: "Ръководство" },
