  rd_cpp_print: { en: "Print", fil: "I-print", zh: "打印", "zh-TW": "列印", vi: "In", th: "พิมพ์", id: "Cetak", bg: "Печат" },
  rd_cpp_soldout_q: { en: "{code} is sold out. Print anyway?", fil: "Ubos na ang {code}. I-print pa rin?", zh: "{code} 已售罄。仍要打印吗？", "zh-TW": "{code} 已售完。仍要列印嗎？", vi: "{code} đã hết hàng. Vẫn in chứ?", th: "{code} หมดแล้ว ยังจะพิมพ์ไหม?", id: "{code} sudah habis. Tetap cetak?", bg: "{code} е изчерпан. Да се отпечата ли все пак?" },
