  rd_cpp_cleared: { en: "{n} waiting comments were cleared", fil: "Na-clear ang {n} naghihintay na comment", zh: "已清除 {n} 条等待中的评论", "zh-TW": "已清除 {n} 則等待中的留言", vi: "Đã xóa {n} bình luận đang chờ", th: "ล้างคอมเมนต์ที่รออยู่ {n} รายการแล้ว", id: "{n} komentar yang menunggu dihapus", bg: "{n} чакащи коментара бяха изчистени" },
  rd_cpp_cleared_one: { en: "1 waiting comment was cleared", fil: "Na-clear ang 1 naghihintay na comment", zh: "已清除 1 条等待中的评论", "zh-TW": "已清除 1 則等待中的留言", vi: "Đã xóa 1 bình luận đang chờ", th: "ล้างคอมเมนต์ที่รออยู่ 1 รายการแล้ว", id: "1 komentar yang menunggu dihapus", bg: "1 чакащ коментар беше изчистен" },
