  rd_shp_mark_shipped: { en: "Mark shipped", fil: "Markahang shipped", zh: "标记已寄件", "zh-TW": "標記已寄件", vi: "Đánh dấu đã gửi", th: "ทำเครื่องหมายส่งแล้ว", id: "Tandai terkirim", bg: "Отбележи като изпратена" },
