  rd_ann_publish: { en: "Publish", fil: "I-publish", zh: "发布", "zh-TW": "發布", vi: "Đăng", th: "เผยแพร่", id: "Terbitkan", bg: "Публикувай" },
  rd_ann_unpublish: { en: "Unpublish", fil: "I-unpublish", zh: "取消发布", "zh-TW": "取消發布", vi: "Gỡ xuống", th: "เลิกเผยแพร่", id: "Batalkan terbit", bg: "Свали от публикация" },
  rd_ann_active_now: { en: "Active now", fil: "Aktibo ngayon", zh: "当前生效", "zh-TW": "目前生效", vi: "Đang hiển thị", th: "ใช้งานอยู่", id: "Aktif sekarang", bg: "Активно сега" },
