  rd_oc_more: { en: "More", fil: "Iba pa", zh: "更多", "zh-TW": "更多", vi: "Thêm", th: "เพิ่มเติม", id: "Lainnya", bg: "Още" },
  rd_oc_title: { en: "Cancel this order?", fil: "I-cancel ang order na ito?", zh: "取消这个订单？", "zh-TW": "取消這筆訂單？", vi: "Hủy đơn này?", th: "ยกเลิกออร์เดอร์นี้ไหม?", id: "Batalkan pesanan ini?", bg: "Да се откаже ли тази поръчка?" },
  rd_oc_l1: { en: "Removed from Sales, totals, Invoicing and receipts.", fil: "Aalisin sa Sales, totals, Invoicing at receipts.", zh: "将从销售、合计、账单和收据中移除。", "zh-TW": "將從銷售、合計、帳單和收據中移除。", vi: "Bị bỏ khỏi Doanh số, tổng, Hóa đơn và biên nhận.", th: "จะถูกนำออกจากยอดขาย ยอดรวม ใบแจ้งหนี้ และใบเสร็จ", id: "Dihapus dari Penjualan, total, Tagihan, dan struk.", bg: "Махат се от Продажби, сумите, Фактуриране и бележките." },
  rd_oc_l2: { en: "Buyer {n} keeps the same number.", fil: "Hindi magbabago ang number ni buyer {n}.", zh: "买家 {n} 的编号不变。", "zh-TW": "買家 {n} 的編號不變。", vi: "Người mua {n} giữ nguyên số.", th: "ผู้ซื้อ {n} ยังใช้หมายเลขเดิม", id: "Pembeli {n} tetap dengan nomor yang sama.", bg: "Купувач {n} запазва същия номер." },
  rd_oc_l3: { en: "The sticker is already printed — throw it away.", fil: "Na-print na ang sticker — itapon na.", zh: "贴纸已打印，请丢掉。", "zh-TW": "貼紙已列印，請丟掉。", vi: "Nhãn đã in rồi — hãy bỏ đi.", th: "สติกเกอร์พิมพ์ไปแล้ว — ทิ้งได้เลย", id: "Stiker sudah tercetak — buang saja.", bg: "Стикерът вече е отпечатан — изхвърлете го." },
  rd_oc_l4: { en: "Changed your mind? Tap Undo on the order.", fil: "Nagbago ang isip? Pindutin ang Undo sa order.", zh: "改变主意？点订单上的“撤销”。", "zh-TW": "改變主意？點訂單上的「復原」。", vi: "Đổi ý? Bấm Hoàn tác trên đơn.", th: "เปลี่ยนใจ? กดเลิกทำที่ออร์เดอร์", id: "Berubah pikiran? Ketuk Urungkan pada pesanan.", bg: "Размислихте? Натиснете „Отмени“ на поръчката." },
  rd_oc_sent: { en: "An invoice or receipt was already sent to this buyer — tell them about the change.", fil: "Na-send na ang invoice o receipt sa buyer na ito — sabihan sila sa pagbabago.", zh: "已给这位买家发过账单或收据，请告诉对方这个变动。", "zh-TW": "已給這位買家傳過帳單或收據，請告訴對方這個變動。", vi: "Đã gửi hóa đơn hoặc biên nhận cho người mua này — hãy báo họ về thay đổi.", th: "ส่งใบแจ้งหนี้หรือใบเสร็จให้ผู้ซื้อคนนี้แล้ว — แจ้งเขาเรื่องการเปลี่ยนแปลง", id: "Tagihan atau struk sudah dikirim ke pembeli ini — beri tahu mereka perubahannya.", bg: "На този купувач вече е изпратена фактура или бележка — кажете му за промяната." },
  rd_oc_keep: { en: "Keep order", fil: "Huwag i-cancel", zh: "保留订单", "zh-TW": "保留訂單", vi: "Giữ đơn", th: "เก็บออร์เดอร์ไว้", id: "Simpan pesanan", bg: "Запази поръчката" },
  rd_oc_yes: { en: "Cancel order", fil: "I-cancel ang order", zh: "取消订单", "zh-TW": "取消訂單", vi: "Hủy đơn", th: "ยกเลิกออร์เดอร์", id: "Batalkan pesanan", bg: "Откажи поръчката" },
