  rd_os_width: { en: "Width (mm)", fil: "Lapad (mm)", zh: "宽 (mm)", "zh-TW": "寬 (mm)", vi: "Rộng (mm)", th: "กว้าง (มม.)", id: "Lebar (mm)", bg: "Ширина (мм)" },
