  rd_ps_sticker: { en: "Sticker", fil: "Sticker", zh: "贴纸", "zh-TW": "貼紙", vi: "Sticker", th: "สติกเกอร์", id: "Stiker", bg: "Стикер" },
  rd_ps_ip: { en: "Printer number (from its test page)", fil: "Number ng printer (mula sa test page)", zh: "打印机号码（见测试页）", "zh-TW": "印表機號碼（見測試頁）", vi: "Số máy in (trên trang thử)", th: "หมายเลขเครื่องพิมพ์ (จากหน้าทดสอบ)", id: "Nomor printer (dari halaman tes)", bg: "Номер на принтера (от тестовата страница)" },
  rd_ps_port: { en: "Second number (usually 9100)", fil: "Pangalawang number (kadalasan 9100)", zh: "第二个号码（通常为 9100）", "zh-TW": "第二個號碼（通常為 9100）", vi: "Số thứ hai (thường là 9100)", th: "หมายเลขที่สอง (ปกติ 9100)", id: "Nomor kedua (biasanya 9100)", bg: "Втори номер (обикновено 9100)" },
