  rd_ps_test_conn: { en: "Test Connection", fil: "Test ng Koneksyon", zh: "测试连接", "zh-TW": "測試連線", vi: "Kiểm tra kết nối", th: "ทดสอบการเชื่อมต่อ", id: "Tes koneksi", bg: "Тест на връзката" },
