  rd_prt_tile: { en: "Printer testers", fil: "Printer testers", zh: "打印机测试员", "zh-TW": "印表機測試員", vi: "Người thử máy in", th: "ผู้ทดสอบเครื่องพิมพ์", id: "Penguji printer", bg: "Тестери на принтери" },
