  rd_adm_fs_reset_q: { en: "Set this live account's free orders back to 0? It has {n} now. The logins' own counts stay.", fil: "Set this live account's free orders back to 0? It has {n} now. The logins' own counts stay.", zh: "Set this live account's free orders back to 0? It has {n} now. The logins' own counts stay.", "zh-TW": "Set this live account's free orders back to 0? It has {n} now. The logins' own counts stay.", vi: "Set this live account's free orders back to 0? It has {n} now. The logins' own counts stay.", th: "Set this live account's free orders back to 0? It has {n} now. The logins' own counts stay.", id: "Set this live account's free orders back to 0? It has {n} now. The logins' own counts stay.", bg: "Set this live account's free orders back to 0? It has {n} now. The logins' own counts stay." },
