  rd_pf_rm_title: { en: "Remove {name}?", fil: "Alisin ang {name}?", zh: "移除 {name}？", "zh-TW": "移除 {name}？", vi: "Xoá {name}?", th: "ลบ {name} ไหม?", id: "Hapus {name}?", bg: "Да премахна ли {name}?" },
  rd_pf_rm_body: { en: "Your orders and stickers stay. You can add a new account right away. After that, it can't be changed again for 4 hours.", fil: "Mananatili ang mga order at sticker mo. Makakapagdagdag ka agad ng bagong account. Pagkatapos noon, hindi na ito mapapalitan ulit sa loob ng 4 na oras.", zh: "您的订单和贴纸都会保留。您可以马上添加新账号。之后 4 小时内不能再更换。", "zh-TW": "您的訂單和貼紙都會保留。您可以馬上新增新帳號。之後 4 小時內不能再更換。", vi: "Đơn hàng và tem của bạn vẫn còn. Bạn có thể thêm tài khoản mới ngay. Sau đó, không thể đổi lại trong 4 giờ.", th: "ออเดอร์และสติกเกอร์ของคุณยังอยู่ คุณเพิ่มบัญชีใหม่ได้ทันที หลังจากนั้นจะเปลี่ยนอีกไม่ได้เป็นเวลา 4 ชั่วโมง", id: "Pesanan dan stiker Anda tetap ada. Anda bisa langsung menambah akun baru. Setelah itu, akun tidak bisa diganti lagi selama 4 jam.", bg: "Поръчките и стикерите ти остават. Можеш да добавиш нов акаунт веднага. След това той не може да се сменя отново 4 часа." },
  rd_pf_rm_body_free: { en: "Your orders and stickers stay. You can add a new account right away.", fil: "Mananatili ang mga order at sticker mo. Makakapagdagdag ka agad ng bagong account.", zh: "您的订单和贴纸都会保留。您可以马上添加新账号。", "zh-TW": "您的訂單和貼紙都會保留。您可以馬上新增新帳號。", vi: "Đơn hàng và tem của bạn vẫn còn. Bạn có thể thêm tài khoản mới ngay.", th: "ออเดอร์และสติกเกอร์ของคุณยังอยู่ คุณเพิ่มบัญชีใหม่ได้ทันที", id: "Pesanan dan stiker Anda tetap ada. Anda bisa langsung menambah akun baru.", bg: "Поръчките и стикерите ти остават. Можеш да добавиш нов акаунт веднага." },
  rd_pf_rm_keep: { en: "Keep it", fil: "Huwag alisin", zh: "保留", "zh-TW": "保留", vi: "Giữ lại", th: "เก็บไว้", id: "Simpan", bg: "Запази го" },
  rd_pf_removing: { en: "Removing…", fil: "Inaalis…", zh: "正在移除…", "zh-TW": "正在移除…", vi: "Đang xoá…", th: "กำลังลบ…", id: "Menghapus…", bg: "Премахване…" },
